export const galleryImages: GalleryImage[] = specs.map(([slug, title, artist, kind, colors, alt], i) => ({
  src: `/gallery/${String(i + 1).padStart(2, "0")}-${slug}.webp`,
  alt,
  title,
  subtitle: artist,
  kind,
  colors,
  seed: 1000 + i * 37,
}));

/** Gallery items (src, alt, title, subtitle) without the generator recipe. */
export const galleryItems = galleryImages.map(({ src, alt, title, subtitle }) => ({ src, alt, title, subtitle }));
